<script setup lang="ts">
import type { Task } from './api'
defineProps<{ task: Task }>()
const json = (value: unknown) => JSON.stringify(value, null, 2) ?? '无返回内容'
</script>
<template><section><p v-if="task.failure_stage" class="field-error">失败阶段：{{ task.failure_stage }}；审核决定与写回确认请分别核对。</p><p>输入来源：{{ task.parse_snapshot.mode }} · 制度：{{ task.policy_version }} · 修订：{{ task.revision }}</p><details v-if="task.parse_snapshot.fallback_event"><summary>模型异常记录</summary><pre>{{ json(task.parse_snapshot.fallback_event) }}</pre></details><details><summary>初始提交与确认记录</summary><pre>{{ json(task.submission_payload) }}</pre><pre>{{ json(task.confirmations) }}</pre></details><details v-if="task.amendments.length"><summary>员工修改历史</summary><pre>{{ json(task.amendments) }}</pre></details><details v-if="task.revisions?.length"><summary>各次修订与来源快照</summary><pre>{{ json(task.revisions) }}</pre></details><h3>工具调用日志</h3><p v-if="!task.logs.length" class="muted">暂无工具调用记录。</p><article v-for="(log,i) in task.logs" :key="i" class="citation"><b>{{ log.tool }} · {{ log.method }} · {{ log.success ? '成功' : '失败' }}</b><p>{{ log.at }} · 耗时 {{ log.duration_ms }} ms</p><p v-if="log.error" class="field-error">调用错误：{{ log.error }}</p><details><summary>请求参数</summary><pre>{{ json(log.request) }}</pre></details><details v-if="log.response != null"><summary>响应结果</summary><pre>{{ json(log.response) }}</pre></details><p v-else class="muted">未记录工具响应。</p></article><h3>审批记录</h3><p v-if="!task.approvals.length" class="muted">暂无人工审批记录。</p><article v-for="(record,i) in task.approvals" :key="i" class="citation"><b>{{ record.decision === 'approve' ? '通过并继续' : record.decision === 'return' ? '退回员工补充' : '拒绝并终止' }} · {{ record.actor }}</b><p>{{ record.comment }}</p><p v-if="record.manual_basis">人工依据：{{ record.manual_basis }}</p><small>{{ record.at }}</small></article></section></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}summary{cursor:pointer;padding:8px 0}</style>
